  document.getElementById('followUpLaterForm').addEventListener('submit',async e=>{e.preventDefault();if(!demo.journeyId)return;const date=document.getElementById('followUpDate').value;const time=getFollowUpTime();const note=document.getElementById('followUpNote').value.trim();if(!date||!time||!note)return;const followUpAt=new Date(`${date}T${time}:00`).getTime();const button=e.currentTarget.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Saving...';try{const response=await fetch(`${API}/ad_journey_follow_up_stage4`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${journeyToken}`},body:JSON.stringify({journey_id:demo.journeyId,follow_up_at:followUpAt,note})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||data.error||data.detail||'Unable to schedule follow-up.');usageEvent('follow_up_scheduled',{module:'journey_panel',action:'schedule',target:'journey',journey_id:demo.journeyId,franchise_id:demo.franchiseId||0,follow_up_at:followUpAt});if(typeof loadBoard==='function')await loadBoard();close();}catch(error){alert(error.message);}finally{button.disabled=false;button.textContent='Save Follow-up';}});
